right=[[6,6,6,6,6,6,6,6],[6,6,6,6,6,6,6,6],[6,6,6,5,6,6,6,6],[6,6,6,6,6,6,6,6],[6,6,6,6,6,6,6,6],[6,6,6,6,6,6,6,6],[6,6,6,6,6,6,6,6],[6,6,5,6,6,6,6,6],[6,6,6,6,6,6,6,6],[6,5,6,6,6,6,6,5],[6,6,6,6,6,6,6,6],[6,6,6,6,6,6,6,6],[6,6,5,6,6,6,6,6]]
A={(r,c) for r,row in enumerate(left) for c,v in enumerate(row) if v==1}; B={(r,c) for r,row in enumerate(right) for c,v in enumerate(row) if v==5}; O={(6,1),(8,5),(11,0)}
print('A count',len(A),'coords',sorted(A)); print('B',sorted(B)); print('output',sorted(O))
# components A
un=set(A); comps=[]
while un:
 p=un.pop(); comp={p}; stack=[p]
 while stack:
  r,c=stack.pop()
  for q in [(r+1,c),(r-1,c),(r,c+1),(r,c-1)]:
   if q in un: un.remove(q); comp.add(q); stack.append(q)
 comps.append(comp)
print('components',[(len(x),sorted(x)) for x in comps])
# Examine coordinate displacement from each right marker to corresponding output? nearest
for b in sorted(B): print(b, sorted(O,key=lambda o:abs(o[0]-b[0])+abs(o[1]-b[1]))[0], 'delta', (sorted(O,key=lambda o:abs(o[0]-b[0])+abs(o[1]-b[1]))[0][0]-b[0],sorted(O,key=lambda o:abs(o[0]-b[0])+abs(o[1]-b[1]))[0][1]-b[1]))
# translated footprint pair overlaps and counts
for dr in range(-12,13):
 for dc in range(-7,8):
  t={(r+dr,c+dc) for r,c in A}
  n=len(t&B)
  if n>=2: print('translation',dr,dc,'overlap',n,'B matched',sorted(t&B),'A placed output?',sorted(t&O))

